import fs from 'node:fs/promises';import path from 'node:path';import crypto from 'node:crypto';import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');const base=JSON.parse(await fs.readFile(path.join(root,'outputs/catalog-quality-stage2b-published-manifest.json'),'utf8'));
const files=['app/services/CatalogProperties.php','app/services/CatalogMigration.php','app/services/CatalogMigrationSource.php','app/services/CatalogMigrationPlan.php','app/controllers/admin/CatalogPropertiesController.php','app/views/itscenter/admin/CatalogProperties/index.php','app/views/itscenter/admin/CatalogProperties/quality.php','app/views/itscenter/admin/CatalogProperties/migrations.php','bin/catalog_migrate.php','bin/catalog_migration_plan.php'];
const out=path.join(root,'outputs/releases/catalog-migration-2c-'+new Date().toISOString().replace(/[:.]/g,'-'));const manifest={release:'catalog-migration-2c',created_at:new Date().toISOString(),production_applied:false,files:[]};
for(const p of files){const b=await fs.readFile(path.join(root,p));const dest=path.join(out,'files',p);await fs.mkdir(path.dirname(dest),{recursive:true});await fs.writeFile(dest,b);manifest.files.push({path:p,sha256:crypto.createHash('sha256').update(b).digest('hex'),bytes:b.length,expected_production_sha256:base.files.find(f=>f.path===p)?.sha256??null});}await fs.writeFile(path.join(out,'manifest.json'),JSON.stringify(manifest,null,2)+'\n');console.log(out);
